
import{setAura,setPadState}from'./cosmic-controller.js';const $=id=>document.getElementById(id);const ui={gpStatus:$('gpStatus'),apiStatus:$('apiStatus'),stateOut:$('stateOut'),deadzone:$('deadzone'),curve:$('curve'),lookSens:$('lookSens'),moveSens:$('moveSens'),triggerCurve:$('triggerCurve'),invertY:$('invertY'),ledColor:$('ledColor'),ledMode:$('ledMode'),kpiDrift:$('kpiDrift'),kpiStress:$('kpiStress'),kpiSym:$('kpiSym'),kpiActivity:$('kpiActivity'),analysisOut:$('analysisOut'),sketchFrame:$('sketchFrame')};for(const input of document.querySelectorAll('input[type=range]')){const span=input.parentElement.querySelector('span');const sync=()=>{if(span)span.textContent=Number(input.value).toFixed(2)};input.addEventListener('input',sync);sync()}const cfg={deadzone:.14,curve:1.35,smoothing:.22,lookSens:2.1,moveSens:1,triggerCurve:1,invertY:false};const state={lx:0,ly:0,rx:0,ry:0,lt:0,rt:0,buttons:{},id:null,ts:0};let smooth={...state},lastSend=0,activity=0,drift=0;function dz(x){const ax=Math.abs(x),dz=cfg.deadzone;if(ax<dz)return 0;const nx=(ax-dz)/Math.max(1e-6,1-dz);return Math.sign(x)*Math.pow(nx,cfg.curve)}function btn(g,i){return!!(g.buttons[i]&&g.buttons[i].pressed)}function poll(){cfg.deadzone=+ui.deadzone.value;cfg.curve=+ui.curve.value;cfg.lookSens=+ui.lookSens.value;cfg.moveSens=+ui.moveSens.value;cfg.triggerCurve=+ui.triggerCurve.value;cfg.invertY=ui.invertY.checked;const gps=navigator.getGamepads?navigator.getGamepads():[];const gp=[...gps].find(Boolean);if(gp){ui.gpStatus.textContent='gamepad: '+gp.id.slice(0,48);state.id=gp.id;state.ts=performance.now();state.lx=dz(gp.axes[0]||0)*cfg.moveSens;state.ly=dz(gp.axes[1]||0)*cfg.moveSens;state.rx=dz(gp.axes[2]||0)*cfg.lookSens;state.ry=dz((gp.axes[3]||0)*(cfg.invertY?-1:1))*cfg.lookSens;state.lt=Math.pow(gp.buttons[6]?.value||0,cfg.triggerCurve);state.rt=Math.pow(gp.buttons[7]?.value||0,cfg.triggerCurve);state.buttons={A:btn(gp,0),B:btn(gp,1),X:btn(gp,2),Y:btn(gp,3),LB:btn(gp,4),RB:btn(gp,5),Back:btn(gp,8),Start:btn(gp,9)}}else ui.gpStatus.textContent='gamepad: none';const a=.25;for(const k of['lx','ly','rx','ry','lt','rt'])smooth[k]=(smooth[k]||0)*(1-a)+(state[k]||0)*a;activity=Math.min(1,Math.abs(smooth.lx)+Math.abs(smooth.ly)+Math.abs(smooth.rx)+Math.abs(smooth.ry)+smooth.lt+smooth.rt);drift=Math.abs(smooth.lx-smooth.rx)*.5+Math.abs(smooth.ly-smooth.ry)*.5;const sym=1-Math.min(1,Math.abs(Math.abs(smooth.lx)-Math.abs(smooth.ly))+Math.abs(Math.abs(smooth.rx)-Math.abs(smooth.ry)));const stress=Math.min(1,activity*.65+drift*.45);ui.kpiDrift.textContent='drift '+drift.toFixed(2);ui.kpiStress.textContent='stress '+stress.toFixed(2);ui.kpiSym.textContent='symmetry '+sym.toFixed(2);ui.kpiActivity.textContent='activity '+activity.toFixed(2);setPadState(smooth,drift);ui.stateOut.textContent=JSON.stringify({state:smooth,buttons:state.buttons,profile:cfg,bi:{activity,drift,sym,stress}},null,2);if(performance.now()-lastSend>500){lastSend=performance.now();sendTelemetry({state:smooth,buttons:state.buttons,profile:cfg,bi:{activity,drift,sym,stress}})}requestAnimationFrame(poll)}requestAnimationFrame(poll);async function sendTelemetry(payload){try{await fetch('/api/telemetry',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});ui.apiStatus.textContent='api: ok'}catch(e){ui.apiStatus.textContent='api: offline'}}$('saveProfile').onclick=async()=>{const profile={name:'web-profile-'+new Date().toISOString(),cfg,led:{color:ui.ledColor.value,mode:ui.ledMode.value}};const r=await fetch('/api/profiles',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(profile)});ui.analysisOut.textContent=JSON.stringify(await r.json(),null,2)};$('sendLed').onclick=async()=>{setAura(ui.ledColor.value);const payload={color:ui.ledColor.value,mode:ui.ledMode.value};const r=await fetch('/api/hardware/led',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});ui.analysisOut.textContent=JSON.stringify(await r.json(),null,2)};$('analyzeBtn').onclick=async()=>{const r=await fetch('/api/agent/analyze',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({state:smooth,cfg})});ui.analysisOut.textContent=JSON.stringify(await r.json(),null,2)};document.querySelectorAll('[data-sketch]').forEach(btn=>btn.onclick=()=>{const src=btn.dataset.sketch;ui.sketchFrame.src=src;ui.sketchFrame.style.display=src?'block':'none'});
